SELECT t.TASK_ID AS task_id,t.PIPELINE_ID AS pipeline_id,p.PROJECT_ID AS project_id,p.PIPELINE_CODE AS pipeline_code,t.TASK_CODE AS task_code,v.PARAMETER_VALUE AS channel_name FROM CFG_TASKS t JOIN CFG_PIPELINES p ON p.PIPELINE_ID=t.PIPELINE_ID JOIN CFG_TASK_PARAMETERS v ON v.TASK_ID=t.TASK_ID AND v.PARAMETER_NAME='ALERT_CHANNEL' AND v.ACTIVE_FLAG='Y' WHERE t.HANDLER='EMAIL_ALERT' AND t.ACTIVE_FLAG='Y' AND p.ACTIVE_FLAG='Y' ORDER BY t.TASK_ID
